// Original institutional letterhead image from AVH_Procedimiento_Compras_Contrataciones.docx.
// The viewport reproduces its OOXML source crop without modifying the logo pixels.
const source="";
export async function embedAvhLogo(pdf){return pdf.embedJpg(source);}
export function drawAvhLogo(page,image,lib,x,y,height=62){
 const crop={left:.43352,right:.43272,top:.01368,bottom:.88826};
 const ratio=image.width*(1-crop.left-crop.right)/(image.height*(1-crop.top-crop.bottom));
 const width=height*ratio,w=width/(1-crop.left-crop.right),h=height/(1-crop.top-crop.bottom);
 page.pushOperators(lib.pushGraphicsState(),lib.rectangle(x,y,width,height),lib.clip(),lib.endPath());
 page.drawImage(image,{x:x-crop.left*w,y:y-crop.bottom*h,width:w,height:h});
 page.pushOperators(lib.popGraphicsState());return width;
}
